INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28h-2016-q31','exam-sg','個人情報保護・OECD原則','standard','single_choice','【2016年度 平成28年春期 午前 問31】OECDプライバシーガイドラインの原則に関する説明のうち，適切なものはどれか。','[{"id":"a","text":"安全保護の原則：個人データの収集を制限し，適法・公正な手段で収集する。"},{"id":"b","text":"個人参加の原則：個人データの取扱い方針を公開する。"},{"id":"c","text":"収集制限の原則：収集目的を収集前に特定し，その目的に沿って利用する。"},{"id":"d","text":"データ内容の原則：個人データを利用目的に沿った必要な範囲で正確・完全・最新に保つ。"}]','"d"','正解はエ。データ内容の原則は，個人データを利用目的に沿って必要な範囲で正確・完全・最新に保つことを求める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q32','exam-sg','個人情報保護法','standard','single_choice','【2016年度 平成28年春期 午前 問32】個人情報保護法に照らして，適切なものはどれか。','[{"id":"a","text":"文字列やドメイン名から特定の個人を識別できるメールアドレスは，個人情報である。"},{"id":"b","text":"個人の業績評価は，個人を識別できる情報を含んでいても個人情報ではない。"},{"id":"c","text":"新聞やインターネットで公表済みの氏名・性別・生年月日は個人情報ではない。"},{"id":"d","text":"法人の所在地や従業員数，代表電話番号は個人情報である。"}]','"a"','正解はア。公表済みであっても，特定の個人を識別できる情報は個人情報に該当し得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q33','exam-sg','法務・電子計算機損壊等業務妨害','standard','single_choice','【2016年度 平成28年春期 午前 問33】刑法における「電子計算機損壊等業務妨害」に該当する行為はどれか。','[{"id":"a","text":"企業が運営するWebサイトに接続し，Webページを改ざんした。"},{"id":"b","text":"他社の商標に酷似したドメイン名を使い，不正に利益を得た。"},{"id":"c","text":"他人のWebサイトを無断複製し，同じサイトを公開した。"},{"id":"d","text":"他人のキャッシュカードでATMを操作し，自分の口座に振り込んだ。"}]','"a"','正解はア。Webサイトを改ざんして業務を妨害する行為は，電子計算機損壊等業務妨害に該当し得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q34','exam-sg','法務・迷惑メール規制','standard','single_choice','【2016年度 平成28年春期 午前 問34】特定電子メール送信適正化法で規制される，いわゆる迷惑メール（スパムメール）はどれか。','[{"id":"a","text":"ウイルス感染を知らずに職場全員へ送った業務連絡メール"},{"id":"b","text":"名簿に掲載された著者のアドレスへ匿名で送った批判メール"},{"id":"c","text":"接客への不満から企業窓口へ繰り返し送ったクレームメール"},{"id":"d","text":"送信の承諾を得ていない不特定多数に送った広告メール"}]','"d"','正解はエ。事前の同意を得ていない不特定多数に送信する広告メールは，迷惑メール規制の対象となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q35','exam-sg','法務・不正競争防止法','standard','single_choice','【2016年度 平成28年春期 午前 問35】不正競争防止法によって保護される対象として規定されているものはどれか。','[{"id":"a","text":"高度な技術的思想の創作である発明"},{"id":"b","text":"翻訳や翻案などによって創作した著作物"},{"id":"c","text":"秘密として管理され，事業活動に有用で公然と知られていない技術上又は営業上の情報"},{"id":"d","text":"法人の発意に基づき職務上作成したプログラム著作物"}]','"c"','正解はウ。営業秘密は秘密管理性・有用性・非公知性を満たす情報であり，不正競争防止法の保護対象となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q36','exam-sg','契約・請負と指揮命令','standard','single_choice','【2016年度 平成28年春期 午前 問36】請負契約の下で，自社が雇用する労働者を契約先の事業所で働かせる場合，適切なものはどれか。','[{"id":"a","text":"勤務時間や出退勤時刻などの労働条件は契約先が定めて管理する。"},{"id":"b","text":"雇用主が自らの指揮命令の下で労働者を業務に従事させる。"},{"id":"c","text":"労働者は契約先で働く期間，契約先との雇用関係も生じる。"},{"id":"d","text":"労働者は契約先の指揮命令を受けるが，雇用関係は変わらない。"}]','"b"','正解はイ。請負では受託側が自ら労働者に指揮命令を行い，発注者が直接指揮命令する形態は偽装請負の問題となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q37','exam-sg','システム監査・スプレッドシート管理','standard','single_choice','【2016年度 平成28年春期 午前 問37】スプレッドシートの利用に係るコントロールの監査で，指摘事項に該当する行為はどれか。','[{"id":"a","text":"組み込まれたロジックの正確性を検算で確認している。"},{"id":"b","text":"業務上の必要に応じてロジックを随時変更し，そのまま上書き保存している。"},{"id":"c","text":"パスワードを設定し，アクセス制御されたサーバに保管している。"},{"id":"d","text":"所定のルールに従ってバックアップしている。"}]','"b"','正解はイ。ロジックの変更管理や承認がないまま上書きすると，誤りや不正な変更を検知できない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q38','exam-sg','システム監査・守秘義務','standard','single_choice','【2016年度 平成28年春期 午前 問38】情報セキュリティ管理基準に基づく守秘義務の監査で，指摘事項に該当するものはどれか。','[{"id":"a","text":"雇用終了をもって守秘義務が解消されることが雇用契約に定められている。"},{"id":"b","text":"所定の勤務時間外にも守秘義務を負うことが雇用契約に定められている。"},{"id":"c","text":"守秘義務を果たさなかった場合に相応の措置をとることが定められている。"},{"id":"d","text":"所定の守秘義務契約書に署名することが定められている。"}]','"a"','正解はア。守秘義務は退職後も継続する必要があるため，雇用終了と同時に解消する規定は不適切である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q39','exam-sg','情報セキュリティ監査・監査対象','standard','single_choice','【2016年度 平成28年春期 午前 問39】情報セキュリティ監査基準に基づいて監査を実施する場合，監査対象と，コンピュータを導入していない部署での監査実施の要否の組合せとして最も適切なものはどれか。','[{"id":"a","text":"監査対象：情報資産／コンピュータ未導入部署の監査：必要"},{"id":"b","text":"監査対象：情報資産／コンピュータ未導入部署の監査：不要"},{"id":"c","text":"監査対象：情報システム／コンピュータ未導入部署の監査：必要"},{"id":"d","text":"監査対象：情報システム／コンピュータ未導入部署の監査：不要"}]','"a"','正解はア。情報セキュリティ監査の対象は情報資産であり，コンピュータを導入していない部署も対象になり得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q40','exam-sg','ITサービスマネジメント・SLA','standard','single_choice','【2016年度 平成28年春期 午前 問40】SLAに記載する内容として，適切なものはどれか。','[{"id":"a","text":"サービス及びサービス目標を特定した，サービス提供者と顧客との間の合意事項"},{"id":"b","text":"サービス提供者が提供する全サービスの特徴，構成要素及び料金"},{"id":"c","text":"サービスデスクなどの内部グループとサービス提供者との合意事項"},{"id":"d","text":"利用者から出されたITサービスに対する業務要件"}]','"a"','正解はア。SLAはサービス提供者と顧客の間でサービス内容や目標水準を合意した文書である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja');
